#!/bin/zsh
IFS=$'\t' read -r name src desc <<< "$1"
P="Edit this product photo of a handmade woven handbag for an online store. Subject: ${desc}. Keep that handbag EXACTLY as it is: same shape, proportions, weave pattern, stitches, colors, hardware, gold logo plate, handles and chain. Do not redraw, restyle or beautify the bag; where parts were hidden, complete them consistently with the visible parts. Remove all overlaid text, captions and graphic elements. Remove any hands, people and props. Place the bag, fully visible and centered with comfortable margins, on a simple real-looking photo setting: warm off-white seamless backdrop, light natural linen or pale wood surface, soft daylight from a window, subtle realistic contact shadow. Must look like a real photograph taken with a camera, natural and understated, not glossy, not CGI, no sparkles, no extra objects."
python3 ~/.claude/skills/image/scripts/nano_banana.py "$P" -i "../raw/$src" -o "$name.png" --aspect 4:5 --size 2K 2>&1 | grep -E 'SAVED|ERR|rror|MODEL_TEXT' | head -2
